import primitive_api as api

def see_interesting():
    return [o for o in api.list_nearby_objects() if o["name"] not in ("floor", "wall", "grass", "agent") and "tree" not in o["name"]]

# Move west until we are south of door 18065
for _ in range(6):
    api.move_direction("west")
    loc = api.observe_world()["agentLocation"]
    inter = see_interesting()
    print(f"At ({loc['x']}, {loc['y']}):", inter)
    # Check if a closed door is 1 step north
    for o in inter:
        if o["name"] == "door" and o["direction"] == "north" and o["distance"] == 1:
            break
    else:
        continue
    break

# Rotate north, open door, move north 3 steps
api.rotate_direction("north")
for o in api.list_accessible_objects():
    if o["name"] == "door" and "closed" in o.get("description", ""):
        print("Opening:", o, api.open_object(o["uuid"]).get("lastActionMessage"))

for _ in range(3):
    api.move_direction("north")
loc = api.observe_world()["agentLocation"]
print(f"After moving north to ({loc['x']}, {loc['y']}):", see_interesting())
